'use client';

import { useRef, type CSSProperties } from 'react';
import { usePlayback } from './use-playback';
import './variable-weight-ramp.css';

export interface VariableWeightRampProps {
  text: string;
  /** Lightest weight in the sweep (1–1000). */
  min?: number;
  /** Heaviest weight in the sweep (1–1000). */
  max?: number;
  /** One full sweep, in milliseconds. */
  duration?: number;
  /** Freeze on a static left-to-right ramp instead of sweeping. */
  paused?: boolean;
  className?: string;
}

/**
 * A wave of font weight that travels through each letter. It is smooth with a
 * variable font (any font with a "wght" axis) and steps between the
 * available weights otherwise. Paused, off screen or with reduced motion, it
 * shows a static ramp from light to heavy.
 */
export function VariableWeightRamp({
  text,
  min = 200,
  max = 800,
  duration = 2400,
  paused = false,
  className = '',
}: VariableWeightRampProps) {
  const root = useRef<HTMLSpanElement>(null);
  const playing = usePlayback(root, paused);
  const letters = Array.from(text);
  const last = Math.max(1, letters.length - 1);

  return (
    <span
      ref={root}
      className={`mg-weight ${className}`}
      data-playing={playing}
      style={
        {
          '--mg-min': min,
          '--mg-max': max,
          '--mg-duration': `${duration}ms`,
        } as CSSProperties
      }
    >
      <span className='mg-weight__sr'>{text}</span>
      <span aria-hidden='true'>
        {letters.map((letter, index) => (
          <span
            key={index}
            className='mg-weight__letter'
            style={
              {
                // Static ramp position and wave delay for this letter.
                '--mg-at': index / last,
                '--mg-delay': `${(-duration * (last - index)) / last / 2}ms`,
              } as CSSProperties
            }
          >
            {letter === ' ' ? ' ' : letter}
          </span>
        ))}
      </span>
    </span>
  );
}

.mg-weight {
  display: inline-block;
}

.mg-weight__letter {
  display: inline-block;
  /* Static ramp: light on the left, heavy on the right. */
  font-weight: calc(
    var(--mg-min) + (var(--mg-max) - var(--mg-min)) * var(--mg-at)
  );
  font-variation-settings: normal;
}

.mg-weight[data-playing='true'] .mg-weight__letter {
  animation: mg-weight-wave var(--mg-duration) ease-in-out infinite;
  animation-delay: var(--mg-delay);
}

.mg-weight__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@keyframes mg-weight-wave {
  0%,
  100% {
    font-weight: var(--mg-min);
  }
  50% {
    font-weight: var(--mg-max);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-weight[data-playing='true'] .mg-weight__letter {
    animation: none;
  }
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

/**
 * Whether a continuous effect should run: its element is on screen, the
 * browser tab is visible and the caller has not paused it. Loops should stop
 * (or set `animation-play-state: paused`) whenever this returns false.
 */
export function usePlayback(
  ref: RefObject<Element | null>,
  paused = false
): boolean {
  const [onScreen, setOnScreen] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') {
      setOnScreen(true);
      return;
    }
    const observer = new IntersectionObserver(([entry]) =>
      setOnScreen(entry.isIntersecting)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  useEffect(() => {
    const update = () => setPageVisible(document.visibilityState !== 'hidden');
    update();
    document.addEventListener('visibilitychange', update);
    return () => document.removeEventListener('visibilitychange', update);
  }, []);

  return onScreen && pageVisible && !paused;
}
